package ru.bububu.silero.stressprobe;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
import ru.bububu.radio.sources.*;
import ru.bububu.radio.core.*;

public class C7SpeechProjectionTest {
 static String project(String raw){return SourceSpeechPlan45.compile(raw).project(0,raw.length());}
 static void carrier(String spoken){FrontendPlan p=new FrontendPlan(new FrontendPlan.Data(),spoken);p.accentInputs();float[] st=new float[p.rawTokens.size()*10],yo=new float[p.rawTokens.size()*10];for(int row=0;row<p.rawTokens.size();row++){st[row*10]=12;yo[row*10]=12;}p.acceptAccent(st,10,yo,10);assertTrue(new CorePlan(p).length>=3);assertTrue(FrontendPlan.basePreserved(p.spoken.replace("+",""),p.annotated.replace("+","")));}
 @Test public void proseSeparatorsArePausesWithoutSpeakingTheirNames(){String spoken=project("Это — пояснение: научно-технический текст.");assertFalse(spoken.contains("дефис"));assertFalse(spoken.contains("тире"));assertFalse(spoken.contains("двоеточие"));assertTrue(spoken.contains("пояснение"));assertTrue(spoken.contains("технический"));carrier(spoken);}
 @Test public void asciiSpacedHyphenAndMarkdownBulletRetainRawSpansAndCompleteFrontend(){
  for(String raw:List.of("Это - пояснение.","- Пояснение.","Первый пункт.\n- Второй пункт.")){
   SourceSpeechPlan45.Plan plan=SourceSpeechPlan45.compile(raw);assertEquals(raw,plan.canonical);
   int hyphen=raw.indexOf('-');assertTrue(plan.atoms.stream().anyMatch(a->a.start==hyphen&&a.end==hyphen+1));
   String spoken=plan.project(0,raw.length());assertFalse(spoken.contains("дефис"));assertFalse(spoken.contains("тире"));
   assertEquals(raw.replace("-", "").replaceAll("[^А-Яа-яЁё]", ""),spoken.replaceAll("[^А-Яа-яЁё]", ""));
   SourceSpeechPlan45.Parts parts=plan.parts(512,t->new FrontendPlan(new FrontendPlan.Data(),t));
   assertEquals(raw.replaceAll("\\s+", ""),String.join("",parts.raw).replaceAll("\\s+", ""));for(String part:parts.spoken)carrier(part);
  }
 }
 @Test public void standaloneNumericAndSymbolicSeparatorsKeepTheirContext(){
  for(String raw:List.of("10 - 20", "х - у")){String spoken=project(raw);assertTrue(spoken,spoken.contains("дефис"));carrier(spoken);}
  for(String raw:List.of("10 – 20", "10 — 20", "a — b")){String spoken=project(raw);assertTrue(spoken,spoken.contains("тире"));carrier(spoken);}
  for(String raw:List.of("10 : 20", "х : у")){String spoken=project(raw);assertTrue(spoken,spoken.contains("двоеточие"));carrier(spoken);}
 }
 @Test public void signedValuesIdentifiersUrlsAndNumericSeparatorsKeepTheirMeaning(){String spoken=project("Значение -15%, модель Т34, ссылка https://example.org/a-b:8 и 10–20.");assertTrue(spoken.contains("минус"));assertTrue(spoken.contains("дефис"));assertTrue(spoken.contains("двоеточие"));assertTrue(spoken.contains("тире"));assertTrue(spoken.contains("тэ"));assertTrue(spoken.contains("процент"));SourceSpeechPlan45.Parts parts=SourceSpeechPlan45.compile("Значение -15%, модель Т34, ссылка https://example.org/a-b:8 и 10–20.").parts(512,s->new FrontendPlan(new FrontendPlan.Data(),s));for(String part:parts.spoken)carrier(part);}
 @Test public void exactInitialismsHaveLetterNamesAndPausesButUppercaseOrdinaryWordDoesNot(){Map<String,String> words=Map.of("КВН","ка, вэ, эн","ВТ","вэ, тэ","ЮФО","ю, эф, о","ЮФУ","ю, эф, у","РФ","эр, эф","США","эс, ша, а","ДНК","дэ, эн, ка","ВПЧ","вэ, пэ, че");for(Map.Entry<String,String> row:words.entrySet()){assertEquals(row.getValue(),project(row.getKey()));assertEquals(row.getValue(),ru.bububu.radio.models.SileroSpeechInput.project(row.getKey()));carrier(project(row.getKey()));}assertEquals("НОВОСТИ",project("НОВОСТИ"));assertEquals("Квн",project("Квн"));assertEquals("СУПЕРКВН",project("СУПЕРКВН"));}
 static SourceVersionRecord oldVersion()throws Exception{SourceProfiles45.Profile profile=SourceProfiles45.byId("biomolecula-articles");SourceRecord source=profile.seed();SourceItem item=SourceItem.create(source.id,"c7",null,"https://biomolecula.ru/articles/c7","Заголовок КВН",-1,-1,1);SourcePublication45 p=new SourcePublication45(SourcePublication45.parse(SourcePublication45.Role.ORIGINAL_PUBLISHED,"2026-10-26","fixture",item.url,"date",false),List.of(),profile.configSha,"fixture","","a".repeat(64));return SourceVersionRecord.source45(source,item,new ExtractionResult("Первое предложение. Второе предложение.","Заголовок КВН","Заголовок КВН","full","","source45-html",SourceProfiles45.PARSER),p,SourcePublication45.Context.DATED,1);}
 @Test public void cachedV2KeepsIdentityBodyAndSentencesWhileMetadataGetsFinishedPhrases()throws Exception{
  SourceVersionRecord before=oldVersion();String raw=before.spokenText,body=before.body(),key=before.versionKey;List<Integer> starts=before.sentenceStarts;java.io.File directory=java.nio.file.Files.createTempDirectory("c7-cas-").toFile();try{SourceBodyCache cache=new SourceBodyCache(directory);cache.put(before);SourceVersionRecord old=cache.get(before.withPayload(null));assertNotNull(old);Article article=old.asArticle();PlayerController.SpeechSentence sentence=new PlayerController.SpeechSentence("SRC:fixture",article,null,0);SourceSpeechPlan45.Plan plan=SourceSpeechPlan45.sentence(sentence);SourceSpeechPlan45.Parts parts=plan.parts(512,s->new FrontendPlan(new FrontendPlan.Data(),s));assertTrue(parts.raw.size()>=3);for(String spoken:parts.spoken){assertTrue(spoken,spoken.endsWith(".")||spoken.endsWith("!")||spoken.endsWith("?"));carrier(spoken);}assertTrue(String.join(" ",parts.spoken).contains("ка, вэ, эн"));assertEquals(raw,old.spokenText);assertEquals(body,old.body());assertEquals(key,old.versionKey);assertEquals(starts,old.sentenceStarts);assertEquals(before.publication.identityDigest(),old.publication.identityDigest());assertEquals(before.bodyHash,old.bodyHash);assertEquals("source-frame-v2",old.framingVersion);
   PlayerController.SpeechUnit unit=new PlayerController.SpeechUnit(sentence,parts.raw,0);String legacyHash=SourceLimits.snapshotVersion("source-speech45-v1","source45-numbers-observed-v2-literal",article.version,"0","0",Integer.toString(parts.raw.get(0).length()),SourceSpeechPlan45.project(unit));assertNotEquals(legacyHash,SourceSpeechPlan45.hash(unit));assertEquals(raw,cache.get(before.withPayload(null)).spokenText);
  }finally{for(java.io.File file:directory.listFiles())file.delete();directory.delete();}
 }
 @Test public void metadataProjectionDoesNotInventAuthorOrChangeBodyOrder()throws Exception{SourceVersionRecord v=oldVersion();Article article=v.asArticle();StringBuilder actual=new StringBuilder();for(int n=1;n<article.sentences.size();n++){PlayerController.SpeechSentence sentence=new PlayerController.SpeechSentence("SRC:fixture",article,null,n);SourceSpeechPlan45.Parts parts=SourceSpeechPlan45.sentence(sentence).parts(512,s->new FrontendPlan(new FrontendPlan.Data(),s));actual.append(String.join(" ",parts.spoken)).append(' ');}assertEquals("Первое предложение. Второе предложение.",actual.toString().trim());assertFalse(v.spokenText.contains("Автор"));}
 @Test public void lookaheadRejectsLegacyProjectionHashEvenWhenCanonicalBodyIsUnchanged()throws Exception{
  SourceVersionRecord v=oldVersion();Article a=v.asArticle();PlayerController.SpeechSentence meta=new PlayerController.SpeechSentence("SRC:fixture",a,null,0);SourceSpeechPlan45.Parts metadata=SourceSpeechPlan45.sentence(meta).parts(512,t->new FrontendPlan(new FrontendPlan.Data(),t));PlayerController.SpeechUnit after=new PlayerController.SpeechUnit(meta,metadata.raw,metadata.raw.size()-1);
  PlayerController.SpeechSentence body=new PlayerController.SpeechSentence("SRC:fixture",a,null,1);SourceSpeechPlan45.Parts parts=SourceSpeechPlan45.sentence(body).parts(512,t->new FrontendPlan(new FrontendPlan.Data(),t));PlayerController.SpeechUnit unit=new PlayerController.SpeechUnit(body,parts.raw,0);
  String legacy=SourceLimits.snapshotVersion("source-speech45-v1","source45-numbers-observed-v2-literal",a.version,"1","0",Integer.toString(parts.raw.get(0).length()),SourceSpeechPlan45.project(unit));assertNotEquals(legacy,SourceSpeechPlan45.hash(unit));
  String prior97d1=SourceLimits.snapshotVersion("source-spoken-runtime45-v2",SourceNumbers45.REVISION,a.version,"1","0",Integer.toString(parts.raw.get(0).length()),SourceSpeechPlan45.project(unit));assertNotEquals(prior97d1,SourceSpeechPlan45.hash(unit));
   for(String stale:List.of(legacy,prior97d1)){ru.bububu.radio.models.RadioLookahead cache=new ru.bububu.radio.models.RadioLookahead();ru.bububu.radio.models.RadioLookahead.Slot slot=cache.reserve(after,SourceSpeechPlan45.RUNTIME_REVISION);assertTrue(cache.planned(slot,unit));java.io.File file=java.io.File.createTempFile("c7-key-",".wav");java.nio.file.Files.write(file.toPath(),new byte[46]);assertFalse(cache.ready(slot,unit,SourceSpeechPlan45.RUNTIME_REVISION,stale,file));assertFalse(file.exists());}
 }

}
